// src/core/user.ts — pure: no await, no fetch, no Date.now()
export type CreateUserResult =
  | { _tag: 'Success'; user: User }
  | { _tag: 'Failure'; error: 'InvalidEmail' | 'WeakPassword' | 'EmailTaken' }

export const createUserLogic = (
  input: CreateUserInput,
  emailTaken: (email: string) => boolean,     // fact passed by the shell
): CreateUserResult =>
  !isValidEmail(input.email) ? { _tag: 'Failure', error: 'InvalidEmail' }
  : emailTaken(input.email)  ? { _tag: 'Failure', error: 'EmailTaken' }
  : { _tag: 'Success', user: { id: input.id, email: input.email.trim().toLowerCase() } }

