// core: plain and pure (no Effect in here)
export const createUserPure = (input: CreateUserInput, emailTaken: boolean): CreateUserResult => ...

// shell: effects described and composed
export const registerUser = (input: CreateUserInput) =>
  Effect.gen(function* () {
    const repo   = yield* UserRepository
    const taken  = yield* repo.emailExists(input.email)
    const result = createUserPure(input, taken)          // pure decision
    if (result._tag === 'Success') yield* repo.save(result.user)
    return result
  })
